styles.css:
@font-face{font-family:"Noto Sans KR";src:url("assets/fonts/NotoSansKR.ttf") format("truetype");font-weight:100 900;font-style:normal;font-display:swap;}
:root{--screen-inset:20px;--section-padding-block:24px;--section-gap:12px;--metadata-gap:16px;--icon-label-gap:8px;--content-gap:20px;--title-gap:8px;--price-gap:12px;--action-pad-block:12px;--action-pad-inline:16px;--action-bg:#5146d7;--action-fg:#fff;--text-primary:#202024;--text-secondary:#60606a}
*{box-sizing:border-box}body{margin:0;color:#202024;background:#f3f3f5;font-family:"Noto Sans KR",sans-serif;font-weight:500;max-width:390px;margin:0 auto}button,input,select{font:inherit}button{cursor:pointer}img{display:block;max-width:100%}p,h1,h2,h3{margin:0}button:focus-visible,a:focus-visible{outline:3px solid #5146d7;outline-offset:4px}.product{display:block;margin:0;padding:0;width:100%}.details{min-width:0}.media-navigation{position:relative;min-width:0}.detail-navigation{position:absolute;z-index:1;left:16px;top:16px}#back{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:50%;background:rgb(255 255 255 / .94);box-shadow:0 2px 12px rgb(0 0 0 / .08)}.product-identity{background:white;padding:28px}#booking-layout{padding-top:12px}.booking-host,.booking-surface{background:#fff;padding:24px 28px}.booking-surface{margin-top:var(--section-gap)}#booking-actions{display:grid;grid-template-columns:48px minmax(0,1fr);align-items:center;gap:12px}.section-label{font-size:14px;font-weight:500;line-height:1.6;color:#60606a;margin-bottom:8px}@media(max-width:700px){.product{display:block;margin:0;padding:0;width:100%}.details{padding:0}.product-identity{padding:var(--section-padding-block) var(--screen-inset)}.booking-host,.booking-surface{padding:var(--section-padding-block) var(--screen-inset)}}
.product-identity,.booking-host,.booking-surface{padding:var(--section-padding-block) var(--screen-inset)}dialog{width:358px;max-width:calc(100% - 32px)}.class-list{max-width:390px;margin:24px auto}

[data-ui-unit="media"].product-media {
  margin: 0;
  width: 100%;
  aspect-ratio: 1 / 1;
}

[data-ui-unit="media"].product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 44% center;
  display: block;
}


[data-ui-unit="identity"].product-identity .eyebrow {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: var(--title-gap);
}

[data-ui-unit="identity"].product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: var(--text-primary);
  word-break: keep-all;
  overflow-wrap: break-word;
}

[data-ui-unit="identity"].product-identity .price-row {
  margin-top: var(--price-gap);
}

[data-ui-unit="identity"].product-identity .price {
  font-size: 24px;
  font-weight: 800;
  color: var(--text-primary);
}

[data-ui-unit="identity"].product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: var(--metadata-gap);
  margin-top: 24px;
}

[data-ui-unit="identity"].product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: var(--icon-label-gap);
}

[data-ui-unit="identity"].product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
  object-fit: contain;
  color: var(--text-secondary);
}

[data-ui-unit="identity"].product-identity .meta-item span {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
}

[data-ui-unit="identity"].product-identity .description {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.75;
  color: var(--text-primary);
  margin-top: var(--content-gap);
  word-break: keep-all;
  overflow-wrap: break-word;
}

[data-ui-unit="booking"]#booking-layout {
  display: flex;
  flex-direction: column;
}


[data-ui-unit="booking"] .booking-host-title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--text-primary);
  margin-top: 8px;
}

[data-ui-unit="booking"] .booking-host-subtitle {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-top: 4px;
}


[data-ui-unit="booking"] #booking-actions {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
}


[data-ui-unit="booking"] .booking-icon-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f2f2f5;
  border-radius: 8px;
  border: none;
  padding: 0;
  cursor: pointer;
  transition: background-color 0.1s ease;
}

[data-ui-unit="booking"] .booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  object-fit: contain;
  color: var(--text-primary);
}

[data-ui-unit="booking"] .booking-icon-btn[aria-pressed="true"] {
  background-color: #e6e1ff;
}

[data-ui-unit="booking"] .booking-icon-btn[aria-pressed="true"] img {
  color: var(--action-bg);
}

[data-ui-unit="booking"] .booking-icon-btn:active {
  transform: scale(0.96);
}


[data-ui-unit="booking"] .booking-primary-btn {
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--action-bg);
  color: var(--action-fg);
  border: none;
  border-radius: 6px;
  padding-block: var(--action-pad-block);
  padding-inline: var(--action-pad-inline);
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  white-space: normal;
  min-width: 0;
  overflow-wrap: break-word;
  text-align: center;
}


[data-ui-unit="booking"] .booking-note {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-top: 12px;
  text-align: center;
}
dialog{width:358px;max-width:calc(100% - 32px);max-height:calc(100dvh - 32px);overflow:auto;border:0;padding:0;border-radius:12px;background:#fff;color:#202024}dialog::backdrop{background:rgb(20 20 24 / .45)}
[data-ui-unit="dialog"].dialog-content {
  display: flex;
  flex-direction: column;
  gap: var(--content-gap);
  padding: 24px;
}

@media (max-width: 360px) {
  [data-ui-unit="dialog"].dialog-content {
    padding: 20px;
  }
}


[data-ui-unit="dialog"] .dialog-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--icon-label-gap);
}

[data-ui-unit="dialog"] .dialog-heading h2 {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  word-break: keep-all;
  overflow-wrap: break-word;
  margin: 0;
  color: var(--text-primary);
}

[data-ui-unit="dialog"] #close-booking {
  flex-shrink: 0;
  min-width: 44px;
  height: 44px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
}

[data-ui-unit="dialog"] #close-booking:hover {
  background-color: rgba(0, 0, 0, 0.05);
}


[data-ui-unit="dialog"] .booking-summary {
  background-color: #f3f3f5;
  padding: 20px;
  border-radius: 8px;
}

[data-ui-unit="dialog"] .section-label {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

[data-ui-unit="dialog"] .booking-class {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 4px 0;
}

[data-ui-unit="dialog"] .booking-price {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  margin: 0;
}


[data-ui-unit="dialog"] #booking-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

[data-ui-unit="dialog"] .booking-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

[data-ui-unit="dialog"] .booking-field label {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.4;
}

[data-ui-unit="dialog"] .field-control {
  position: relative;
  border: 1px solid #dcdce0;
  border-radius: 6px;
  overflow: hidden; 
}


[data-ui-unit="dialog"] .field-control:focus-within {
  outline: 2px solid var(--action-bg);
  outline-offset: -2px; 
}


[data-ui-unit="dialog"] .field-control input,
[data-ui-unit="dialog"] .field-control select {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  padding: 12px;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.5;
  border: none;
  background-color: #fff;
  color: var(--text-primary);
  appearance: none;
}

[data-ui-unit="dialog"] .field-control input::placeholder {
  color: #999;
  font-weight: 400;
}


@media (forced-colors: active) {
  [data-ui-unit="dialog"] .field-control:focus-within {
    outline-color: Highlight;
  }
  [data-ui-unit="dialog"] .field-control input,
  [data-ui-unit="dialog"] .field-control select {
    border: 1px solid CanvasText;
  }
}


[data-ui-unit="dialog"] #storage-error,
[data-ui-unit="dialog"] #cancel-error {
  font-size: 14px;
  font-weight: 500;
  color: #d32f2f;
  margin: 0;
  padding: 0 4px;
}


[data-ui-unit="dialog"] .confirm-booking {
  min-height: 52px;
  width: 100%;
  padding: 16px;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  color: var(--action-fg);
  background-color: var(--action-bg);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  text-align: center;
  white-space: normal;
}

[data-ui-unit="dialog"] .confirm-booking:hover {
  opacity: 0.9;
}

[data-ui-unit="dialog"] #cancel-booking {
  min-width: 44px;
  height: 44px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 8px;
}

[data-ui-unit="dialog"] #cancel-booking:hover {
  background-color: rgba(0, 0, 0, 0.05);
}


[data-ui-unit="dialog"] #confirmation {
  display: flex;
  flex-direction: column;
  gap: var(--content-gap);
}

[data-ui-unit="dialog"] .confirmation-intro {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-primary);
  margin: 0;
}

[data-ui-unit="dialog"] #confirmation-details {
  font-size: 14px;
  line-height: 1.6;
  white-space: pre-line;
  word-break: keep-all;
  overflow-wrap: break-word;
  color: var(--text-primary);
  margin: 0;
}


[data-ui-unit="dialog"] #booking-form[hidden] {
  display: none;
}

[data-ui-unit="dialog"] #confirmation[hidden] {
  display: none;
}
.class-list{max-width:720px;margin:48px auto;padding:0 20px}.class-list h1{font-size:28px;line-height:1.5;margin-bottom:24px}.class-link{display:block;color:inherit;text-decoration:none;background:#fff;border-radius:12px;overflow:hidden}.class-link img{width:100%;aspect-ratio:16/10;object-fit:cover}.class-copy{padding:24px}.class-copy h2{font-size:20px;line-height:1.5;margin:8px 0 16px}.class-copy p{line-height:1.7}.class-list{max-width:390px;margin:24px auto}

.dialog-sample{width:358px;max-width:calc(100% - 32px);margin:16px auto}
